  ('649833cc-e062-46ba-9017-d02c2c0fe5b3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'f6e5c68a-b8b9-428d-9483-5a5ec5f4317d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ध््वनित दिशाएँ उदार, शतममुख-शतरव-ममुखरे!$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-41-732Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a56f1990-5bbf-4306-8c19-0adf494f4075', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'f6e5c68a-b8b9-428d-9483-5a5ec5f4317d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भारति, जय, विजयकरे! कनक-शस््य-कममलधरे! लंका पदतल शतदल, गर््जजितोर््ममि सागर-जल धोता शुचि चरण युगल$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-41-732Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('eb5e4c0d-ea9c-476e-932e-ccff1b852249', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'f6e5c68a-b8b9-428d-9483-5a5ec5f4317d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तरु-तृृण-वन-लता वसन, अंचल मेें खचित सुमन; गंगा ज््ययोतिर््जल-कण धवल धार हार गले।मम ुकुट शुभ्र हिमम-तुषार,$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-41-732Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6a15de0f-c3c7-4bf9-aeff-a0e2afeb3400', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'f6e5c68a-b8b9-428d-9483-5a5ec5f4317d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$प्राण प्रणव ओंकार, ध््वनित दिशाएँ उदार, शतममुख-शतरव-ममुखरे! भारति, जय, विजयकरे!$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-41-732Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('fede96c8-92fd-4d58-80c5-93c14509df4d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'f6e5c68a-b8b9-428d-9483-5a5ec5f4317d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भारति, जय, विजयकरे! कनक-शस््य-कममलधरे!$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-41-732Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('26c72260-fae8-4ea6-9641-ab8933ec50d3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'f6e5c68a-b8b9-428d-9483-5a5ec5f4317d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लंका पदतल शतदल, गर््जजितोर््ममि सागर-जल$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-41-732Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d5e620f7-ec5a-413c-8257-d977b1567e17', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'f6e5c68a-b8b9-428d-9483-5a5ec5f4317d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सूर््यकांत त्रिपाठी ‘निराला’ का जन््म सन् 1899 मेें बंगाल के महिषादल मेें हुआ। वे ममूलतः गढ़ाकोला (उन््ननाव), उत्तर प्रदेश के निवासी थे। निराला की औपचारिक शिक्ा नौवीं तक महिषादल मेें ही हुई। उन््होंने स्वाध््ययाय से संस्ककृत, बांग्ला और अंग्ेजी का ज्ञान अर््जजित किया। उनकी प्रममुख काव््य रचनाएँ हैं— अनामिका, परिमल, गीतिका, कुकुरमुत्ा और नए पत्ते। उपन््ययास, कहानी, आलोचना और निबंध लेखन मेें भी उनकी ख््ययाति अविस््मरणीय है। निराला रचनावली के आठ खंडोों मेें उनका संपूर््ण साहित््य प्रकाशित है। दार््शनिकता, विद्रोह, क््राांति, प्रेमम की तरलता और प्रकृति का विराट तथा उदात्त चित्र उनकी रचनाओं मेें उपस््थथित है। छायावादी रचनाकारों मेें उन््होंने सबसे पहले ममुक्त छंद का प्रयोग किया। उपेक्षितों और पीड़़ितों के प्रति उनकी कविताओं मेें गहरी सहानुभूति मिलती है। ‘निराला’ का निधन सन् 1961 मेें हुआ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-41-732Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('72ae634b-db2f-4366-aa03-5fb45dffac98', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'f6e5c68a-b8b9-428d-9483-5a5ec5f4317d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'भारति, जय, विजयकरेे!’ कविता ‘निराला’ की देेशप्रेम सेे ओत-प्रोत एक प्रेरणादायक रचना है। कविता केे आरंभ में ही कवि ‘भारति, जय, विजयकरेे!’ कहकर भारत कोो विजयश्ी प्ाप्‍त करनेे की कामना करता है। वह भारतभूमि कोो ‘कनक-शस्य-कमलधरेे!’ कहकर संबोधित करता है जोो भारत की कृषि-परंपरा और श्रम केे सौंदर्य कोो दर््शाता है। कविता में भारत की भौगोलिक सुंदरता का ऐसा चित्र खीींचा गया है मानोो भारत कोोई देेवी होो, जिसकेे चरणों कोो समुद्र अपनेे जल सेे धोता है। नदी, वन, पुष्प, हिमालय, गंगा आदि प्ाकृतिक शोोभा कोो भारत केे वस्‍‍त््रा्राभूषण की तरह प्रस््तुत किया गया है। कवि भारत कोो एक चेतन सत्ा केे रूप में देखता है, जिसकी दिशाओं में ‘ओंकार’ की गूँज होो रही है और जोो अनेेक तरह केे स््वरों और विचारों सेे समृद्ध है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-41-732Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('80368870-8eca-44a4-b764-612fece3774e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'f6e5c68a-b8b9-428d-9483-5a5ec5f4317d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सूर््यकांत त्रिपाठी ‘निराला’ का जन््म सन् 1899 मेें बंगाल के महिषादल मेें हुआ। वे ममूलतः गढ़ाकोला (उन््ननाव), उत्तर प्रदेश के निवासी थे। निराला की औपचारिक शिक्ा नौवीं तक महिषादल मेें ही हुई। उन््होंने स्वाध््ययाय से संस्ककृत, बांग्ला और अंग्ेजी का ज्ञान अर््जजित किया। उनकी प्रममुख काव््य रचनाएँ हैं— अनामिका, परिमल, गीतिका, कुकुरमुत्ा और नए पत्ते। उपन््ययास, कहानी, आलोचना और निबंध लेखन मेें भी उनकी ख््ययाति अविस््मरणीय है। निराला रचनावली के आठ खंडोों मेें उनका संपूर््ण साहित््य प्रकाशित है। दार््शनिकता, विद्रोह, क््राांति, प्रेमम की तरलता और प्रकृति का विराट तथा उदात्त चित्र उनकी रचनाओं मेें उपस््थथित है। छायावादी रचनाकारों मेें उन््होंने सबसे पहले ममुक्त छंद का प्रयोग किया। उपेक्षितों और पीड़़ितों के प्रति उनकी कविताओं मेें गहरी सहानुभूति मिलती है। ‘निराला’ का निधन सन् 1961 मेें हुआ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-41-732Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('11a88a2d-64ff-419d-b6ba-9a59a11f74a7', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'f6e5c68a-b8b9-428d-9483-5a5ec5f4317d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'भारति, जय, विजयकरेे!’ कविता ‘निराला’ की देेशप्रेम सेे ओत-प्रोत एक प्रेरणादायक रचना है। कविता केे आरंभ में ही कवि ‘भारति, जय, विजयकरेे!’ कहकर भारत कोो विजयश्ी प्ाप्‍त करनेे की कामना करता है। वह भारतभूमि कोो ‘कनक-शस्य-कमलधरेे!’ कहकर संबोधित करता है जोो भारत की कृषि-परंपरा और श्रम केे सौंदर्य कोो दर््शाता है। कविता में भारत की भौगोलिक सुंदरता का ऐसा चित्र खीींचा गया है मानोो भारत कोोई देेवी होो, जिसकेे चरणों कोो समुद्र अपनेे जल सेे धोता है। नदी, वन, पुष्प, हिमालय, गंगा आदि प्ाकृतिक शोोभा कोो भारत केे वस्‍‍त््रा्राभूषण की तरह प्रस््तुत किया गया है। कवि भारत कोो एक चेतन सत्ा केे रूप में देखता है, जिसकी दिशाओं में ‘ओंकार’ की गूँज होो रही है और जोो अनेेक तरह केे स््वरों और विचारों सेे समृद्ध है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-41-732Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
